    method: "POST",
    headers: {
      Authorization: `Bearer ${process.env.PAY_API_KEY}`,
      "Content-Type": "application/json",
      ...(idempotencyKey && { "Idempotency-Key": idempotencyKey }),
    },
    body: JSON.stringify({ customerId: customer.id, amount: amountMinorUnits, currency: "USD" }),
